<?php
namespace Tests\Feature;
use App\Models\{Dashboard,DashboardWidget,DeviceAccessAssignment,Notification,Organization,ResourcePublicationSubmission,ResourcePublicationVersion,ResourceRevision,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
final class DashboardPublicationTest extends TestCase
{
 use RefreshDatabase;
 private function fixture():array{$org=Organization::create(['name'=>'Published Dashboards','slug'=>'published-dashboards']);$owner=User::factory()->create(['organization_id'=>$org->id,'role'=>'staff','status'=>'active']);$viewer=User::factory()->create(['organization_id'=>$org->id,'role'=>'staff','status'=>'active']);$admin=User::factory()->create(['organization_id'=>$org->id,'role'=>'admin','platform_role'=>'platform_admin','status'=>'active']);$peerAdmin=User::factory()->create(['organization_id'=>$org->id,'role'=>'admin','platform_role'=>'platform_admin','status'=>'active']);$foreignOrg=Organization::create(['name'=>'Foreign','slug'=>'published-dashboard-foreign']);$foreign=User::factory()->create(['organization_id'=>$foreignOrg->id,'role'=>'staff','status'=>'active']);$foreignAdmin=User::factory()->create(['organization_id'=>$foreignOrg->id,'role'=>'admin','platform_role'=>'platform_admin','status'=>'active']);$device=$org->devices()->create(['name'=>'Secret Pump','external_id'=>'published-pump','type'=>'sensor','protocol'=>'mqtt','status'=>'online']);DeviceAccessAssignment::create(['device_id'=>$device->id,'user_id'=>$owner->id,'access_level'=>'full_access']);$dashboard=Dashboard::create(['organization_id'=>$org->id,'owner_user_id'=>$owner->id,'name'=>'Operations','scope_type'=>'personal','created_by'=>$owner->id,'updated_by'=>$owner->id]);DashboardWidget::create(['id'=>(string)Str::uuid(),'dashboard_id'=>$dashboard->id,'widget_type'=>'metric','title'=>'Pressure','layout'=>['x'=>0,'y'=>0,'w'=>3,'h'=>3],'configuration'=>['deviceId'=>$device->id,'telemetryKey'=>'pressure','unit'=>'psi'],'position'=>0]);return compact('org','owner','viewer','admin','peerAdmin','foreign','foreignAdmin','device','dashboard');}
 private function baseline(array $f):array{return $this->actingAs($f['owner'])->getJson("/api/dashboards/{$f['dashboard']->id}")->assertOk()->json();}
 public function test_revision_pinned_approval_publishes_immutable_version_and_not_newer_private_revision():void{$f=$this->fixture();$first=$this->baseline($f);$submission=$this->actingAs($f['owner'])->postJson("/api/dashboards/{$f['dashboard']->id}/publication-submissions",['revision_id'=>$first['baseRevisionId']])->assertCreated()->assertJsonPath('data.status','submitted')->json('data.id');$first['name']='New private name';$this->actingAs($f['owner'])->putJson("/api/dashboards/{$f['dashboard']->id}",$first)->assertOk();$this->actingAs($f['admin'])->postJson("/api/admin/dashboard-publication-submissions/{$submission}/claim")->assertOk();$this->actingAs($f['admin'])->postJson("/api/admin/dashboard-publication-submissions/{$submission}/approve",['confirm_older_revision'=>true])->assertOk()->assertJsonPath('data.status','approved')->assertJsonPath('data.publicationVersion.number',1);$this->assertDatabaseHas('resource_publication_versions',['resource_type'=>'dashboard','resource_id'=>$f['dashboard']->id,'publication_number'=>1,'resource_revision_id'=>(int)$first['baseRevisionId']]);$this->actingAs($f['viewer'])->getJson('/api/dashboards/published/catalog')->assertOk()->assertJsonCount(1,'data')->assertJsonPath('data.0.name','Operations');$this->actingAs($f['viewer'])->getJson("/api/dashboards/published/{$f['dashboard']->id}")->assertOk()->assertJsonPath('data.name','Operations')->assertJsonPath('data.canEdit',false)->assertJsonPath('data.widgets.0.available',false)->assertJsonPath('data.widgets.0.settings.datasource',null)->assertJsonMissing(['comments'])->assertJsonMissing(['collaborators']);$this->actingAs($f['owner'])->getJson("/api/dashboards/{$f['dashboard']->id}")->assertOk()->assertJsonPath('name','New private name');$this->actingAs($f['foreign'])->getJson("/api/dashboards/published/{$f['dashboard']->id}")->assertNotFound();}
 public function test_published_viewer_with_independent_device_access_gets_source_and_terminal_submission_is_idempotently_protected():void{$f=$this->fixture();$first=$this->baseline($f);$submission=$this->actingAs($f['owner'])->postJson("/api/dashboards/{$f['dashboard']->id}/publication-submissions",['revision_id'=>$first['baseRevisionId']])->assertCreated()->json('data.id');$this->actingAs($f['admin'])->postJson("/api/admin/dashboard-publication-submissions/{$submission}/claim")->assertOk();$this->actingAs($f['admin'])->postJson("/api/admin/dashboard-publication-submissions/{$submission}/approve")->assertOk();DeviceAccessAssignment::create(['device_id'=>$f['device']->id,'user_id'=>$f['viewer']->id,'access_level'=>'viewer']);$this->actingAs($f['viewer'])->getJson("/api/dashboards/published/{$f['dashboard']->id}")->assertOk()->assertJsonPath('data.widgets.0.available',true)->assertJsonPath('data.widgets.0.settings.datasource.deviceId',(string)$f['device']->id);$this->actingAs($f['admin'])->postJson("/api/admin/dashboard-publication-submissions/{$submission}/approve")->assertUnprocessable();$this->assertSame(1,ResourcePublicationVersion::where(['resource_type'=>'dashboard','resource_id'=>$f['dashboard']->id])->count());}
 public function test_only_personal_editable_dashboard_and_matching_revision_can_be_submitted():void{$f=$this->fixture();$first=$this->baseline($f);$this->actingAs($f['viewer'])->postJson("/api/dashboards/{$f['dashboard']->id}/publication-submissions",['revision_id'=>$first['baseRevisionId']])->assertNotFound();$other=Dashboard::create(['organization_id'=>$f['org']->id,'owner_user_id'=>$f['owner']->id,'name'=>'Other','scope_type'=>'personal']);$this->actingAs($f['owner'])->postJson("/api/dashboards/{$f['dashboard']->id}/publication-submissions",['revision_id'=>999999])->assertNotFound();$deviceDashboard=Dashboard::create(['organization_id'=>$f['org']->id,'device_id'=>$f['device']->id,'name'=>'Device','scope_type'=>'device']);$this->actingAs($f['owner'])->postJson("/api/dashboards/{$deviceDashboard->id}/publication-submissions",['revision_id'=>$first['baseRevisionId']])->assertUnprocessable();$this->assertSame(0,ResourcePublicationVersion::count());}
 public function test_admin_submission_publishes_immediately_and_notifies_only_peer_admins_in_the_organization():void{$f=$this->fixture();$f['dashboard']->update(['owner_user_id'=>$f['admin']->id,'created_by'=>$f['admin']->id,'updated_by'=>$f['admin']->id]);DeviceAccessAssignment::create(['device_id'=>$f['device']->id,'user_id'=>$f['admin']->id,'access_level'=>'full_access']);$first=$this->actingAs($f['admin'])->getJson("/api/dashboards/{$f['dashboard']->id}")->assertOk()->json();$response=$this->actingAs($f['admin'])->postJson("/api/dashboards/{$f['dashboard']->id}/publication-submissions",['revision_id'=>$first['baseRevisionId']])->assertCreated()->assertJsonPath('data.status','approved')->assertJsonPath('data.publicationVersion.number',1);$submissionId=$response->json('data.id');$this->assertDatabaseHas('resource_publication_versions',['resource_type'=>'dashboard','resource_id'=>$f['dashboard']->id,'resource_revision_id'=>(int)$first['baseRevisionId']]);$this->assertFalse(ResourcePublicationSubmission::whereKey($submissionId)->whereIn('status',ResourcePublicationSubmission::ACTIVE_STATUSES)->exists());$notification=Notification::where('user_id',$f['peerAdmin']->id)->where('type','dashboard.publication.published')->firstOrFail();$this->assertFalse((bool)$notification->requires_action);$this->assertStringContainsString($f['admin']->name,$notification->message);$this->assertStringContainsString($f['dashboard']->name,$notification->message);$this->assertFalse(Notification::where('user_id',$f['admin']->id)->where('type','dashboard.publication.published')->exists());$this->assertFalse(Notification::where('user_id',$f['foreignAdmin']->id)->where('type','dashboard.publication.published')->exists());}
}
